"""A workflow is simply an ordered list of stages in YAML."""

from __future__ import annotations

from typing import Any

import yaml
from pydantic import BaseModel, Field

from videoforge.paths import workflows_dir


class WorkflowStage(BaseModel):
    name: str
    gate_after: bool = False  # pause after the stage until a human approves the result
    options: dict[str, Any] = Field(default_factory=dict)


class Workflow(BaseModel):
    name: str
    description: str = ""
    # Whether the final video contains imagery or voice GENERATED by a model, which
    # platforms ask to label as altered/synthetic content. It is a workflow property,
    # not a publish option: `ai_video` generates frames and synthesizes narration,
    # while `clips_from_long` cuts real footage with real voices. Labelling a real
    # interview as synthetic is not caution but misinforms viewers. Defaults to true:
    # a new workflow whose author did not consider this more likely generates than cuts.
    synthetic: bool = True
    stages: list[WorkflowStage]

    def stage_names(self) -> list[str]:
        return [s.name for s in self.stages]


def load_workflow(name: str) -> Workflow:
    path = workflows_dir() / f"{name}.yaml"
    if not path.exists():
        raise FileNotFoundError(f"workflow '{name}' не найден: {path}")
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    data.setdefault("name", name)
    return Workflow.model_validate(data)


def list_workflows() -> list[str]:
    d = workflows_dir()
    return sorted(p.stem for p in d.glob("*.yaml")) if d.exists() else []
